diff --git a/src/rpc/rpc_record_dispatch.c b/src/rpc/rpc_record_dispatch.c
index c37510d..8b6fffb 100644
--- a/src/rpc/rpc_record_dispatch.c
+++ b/src/rpc/rpc_record_dispatch.c
@@ -10,6 +10,8 @@
 #include "tr/status.h"

 #include <stdlib.h>
+#include <stdio.h>
+#include <inttypes.h>
 #include <stdatomic.h>
 #include <string.h>
 #include <time.h>
@@ -206,7 +208,29 @@ enum tr_dispatch_job_stage {
 	TR_DISPATCH_JOB_APPLICATION = 0,
 	TR_DISPATCH_JOB_AUTHORIZATION = 1
 };
+static uint64_t tr_dispatch_probe_now(void)
+{
+	struct timespec value;
+	if (clock_gettime(CLOCK_MONOTONIC, &value) != 0)
+		abort();
+	return (uint64_t)value.tv_sec * UINT64_C(1000000000) +
+	       (uint64_t)value.tv_nsec;
+}
+static void tr_dispatch_probe_observe(uint64_t hist[34], uint64_t value)
+{
+	unsigned bucket = 0U;
+	uint64_t bound = 1000U;
+	while (value > bound && bucket < 31U) {
+		bound <<= 1U;
+		bucket++;
+	}
+	hist[bucket]++;
+	hist[32] += value;
+	if (value > hist[33])
+		hist[33] = value;
+}
 struct tr_dispatch_job {
+	uint64_t probe_submit, probe_begin, probe_end;
 	struct tr_dispatch_job *next;
 	struct tr_dispatch_slot *slot;
 	enum tr_dispatch_job_stage stage;
@@ -263,6 +287,8 @@ struct tr_dispatch_slot {
 	bool producer_failed;
 };
 struct tr_rpc_record_dispatch {
+	uint64_t probe_pumps, probe_visits, probe_active;
+	uint64_t probe_queue[34], probe_work[34], probe_delivery[34];
 	struct tr_reactor *reactor;
 	struct tr_channel *channel;
 	struct tr_task_executor *executor;
@@ -1100,7 +1126,7 @@ tr_dispatch_authorization_decode(uint64_t value)
 	};
 }

-static int tr_dispatch_work(void *arg, const struct tr_task_cancel *cancel)
+static int tr_dispatch_work_impl(void *arg, const struct tr_task_cancel *cancel)
 {
 	struct tr_dispatch_job *job = arg;
 	struct tr_rpc_record_reply *reply = &job->reply;
@@ -1290,6 +1316,14 @@ static void tr_dispatch_authorization_done(struct tr_dispatch_job *job,
 	}
 	tr_dispatch_settle(s);
 }
+static int tr_dispatch_work(void *arg, const struct tr_task_cancel *cancel)
+{
+	struct tr_dispatch_job *job = arg;
+	job->probe_begin = tr_dispatch_probe_now();
+	int ret = tr_dispatch_work_impl(arg, cancel);
+	job->probe_end = tr_dispatch_probe_now();
+	return ret;
+}
 static void tr_dispatch_done(void *arg, struct tr_task_handle handle,
                              struct tr_task_result result)
 {
@@ -1297,6 +1331,11 @@ static void tr_dispatch_done(void *arg, struct tr_task_handle handle,
 	struct tr_dispatch_slot *s = job->slot;
 	struct tr_rpc_record_dispatch *d = s->dispatch;
 	bool acquired = job->reply.producer != NULL;
+	if (job->probe_begin && job->probe_end) {
+		tr_dispatch_probe_observe(d->probe_queue, job->probe_begin - job->probe_submit);
+		tr_dispatch_probe_observe(d->probe_work, job->probe_end - job->probe_begin);
+		tr_dispatch_probe_observe(d->probe_delivery, tr_dispatch_probe_now() - job->probe_end);
+	}
 	(void)handle;
 	if (job->stage == TR_DISPATCH_JOB_AUTHORIZATION) {
 		if (d->cleanup) {
@@ -1606,6 +1645,7 @@ static bool tr_dispatch_submit(struct tr_dispatch_slot *s)
 		job->authorization_accepted = false;
 	}
 	spec = (struct tr_task_spec){tr_dispatch_work, tr_dispatch_done, job};
+	job->probe_submit = tr_dispatch_probe_now();
 	ret = tr_task_executor_submit(d->executor, &spec, &s->task);
 	if (ret == TR_OK) {
 		s->head = job->next;
@@ -2120,12 +2160,16 @@ int tr_rpc_record_dispatch_pump_on_owner(struct tr_rpc_record_dispatch *d,
 	++d->depth;
 	if (limit > d->config.capacity)
 		limit = d->config.capacity;
+	d->probe_pumps++;
 	while (limit--) {
+		d->probe_visits++;
 		struct tr_dispatch_slot *s = &d->slots[d->cursor];
 		if (++d->cursor == d->config.capacity)
 			d->cursor = 0;
-		if (s->active)
+		if (s->active) {
+			d->probe_active++;
 			tr_dispatch_step(s);
+		}
 	}
 	--d->depth;
 	return TR_OK;
@@ -2232,6 +2276,18 @@ static int tr_dispatch_free(struct tr_rpc_record_dispatch **p)
 	free(d->contexts);
 	free(d->slots);
 	free(d->methods);
+	fprintf(stderr, "{\"type\":\"dispatch_progress_probe\",\"capacity\":%u,"
+	        "\"pumps\":%" PRIu64 ",\"visits\":%" PRIu64 ",\"active\":%" PRIu64
+	        ",\"hist_queue_work_delivery\":[", d->config.capacity,
+	        d->probe_pumps, d->probe_visits, d->probe_active);
+	uint64_t *probe_histograms[] = {d->probe_queue, d->probe_work, d->probe_delivery};
+	for (unsigned i = 0U; i < 3U; ++i) {
+		fprintf(stderr, "%s[", i ? "," : "");
+		for (unsigned j = 0U; j < 34U; ++j)
+			fprintf(stderr, "%s%" PRIu64, j ? "," : "", probe_histograms[i][j]);
+		fprintf(stderr, "]");
+	}
+	fprintf(stderr, "]}\n");
 	free(d);
 	*p = NULL;
 	return tr_memory_budget_release(budget, bytes);
diff --git a/src/rpc/rpc_record_endpoint.c b/src/rpc/rpc_record_endpoint.c
index b3ba34c..0cf3f52 100644
--- a/src/rpc/rpc_record_endpoint.c
+++ b/src/rpc/rpc_record_endpoint.c
@@ -7,6 +7,8 @@
 #include "tr/status.h"

 #include <stdatomic.h>
+#include <stdio.h>
+#include <inttypes.h>
 #include <stdlib.h>
 #include <time.h>

@@ -37,7 +39,16 @@ struct tr_endpoint_slot {
 	bool active, terminal, reported, peer_closed, dead, close_accepted;
 	bool reset_accepted;
 };
+static uint64_t tr_progress_probe_clock(clockid_t clock)
+{
+	struct timespec value;
+	if (clock_gettime(clock, &value) != 0)
+		abort();
+	return (uint64_t)value.tv_sec * UINT64_C(1000000000) +
+	       (uint64_t)value.tv_nsec;
+}
 struct tr_rpc_record_endpoint {
+	uint64_t probe_calls, probe_cpu, probe_wall, probe_max_wall;
 	struct tr_reactor *reactor;
 	struct tr_channel *channel;
 	struct tr_task_executor *executor;
@@ -454,6 +465,8 @@ int tr_rpc_record_endpoint_pump_on_owner(struct tr_rpc_record_endpoint *ep)
 		return ret;
 	if (ep->depth || ep->notifying)
 		return TR_ERR_STATE;
+	uint64_t probe_cpu = tr_progress_probe_clock(CLOCK_THREAD_CPUTIME_ID);
+	uint64_t probe_wall = tr_progress_probe_clock(CLOCK_MONOTONIC);
 	++ep->depth;
 	event_budget = ep->config.progress_limit;
 	tr_endpoint_apply_deferred(ep, &event_budget);
@@ -496,6 +509,13 @@ int tr_rpc_record_endpoint_pump_on_owner(struct tr_rpc_record_endpoint *ep)
 	}
 out:
 	--ep->depth;
+	probe_cpu = tr_progress_probe_clock(CLOCK_THREAD_CPUTIME_ID) - probe_cpu;
+	probe_wall = tr_progress_probe_clock(CLOCK_MONOTONIC) - probe_wall;
+	ep->probe_calls++;
+	ep->probe_cpu += probe_cpu;
+	ep->probe_wall += probe_wall;
+	if (probe_wall > ep->probe_max_wall)
+		ep->probe_max_wall = probe_wall;
 	tr_endpoint_publish_progress(ep, false);
 	return ret;
 }
@@ -640,6 +660,11 @@ static int tr_endpoint_free(struct tr_rpc_record_endpoint **pointer)
 	ep->progress_notify = NULL;
 	ep->progress_arg = NULL;
 	tr_endpoint_frames_put(ep->frames);
+	fprintf(stderr, "{\"type\":\"endpoint_cpu_probe\",\"capacity\":%zu,"
+	        "\"calls\":%" PRIu64 ",\"cpu_ns\":%" PRIu64
+	        ",\"wall_sum_ns\":%" PRIu64 ",\"wall_max_ns\":%" PRIu64 "}\n",
+	        ep->capacity, ep->probe_calls, ep->probe_cpu,
+	        ep->probe_wall, ep->probe_max_wall);
 	free(ep);
 	*pointer = NULL;
 	return tr_memory_budget_release(budget, bytes);

