index b012c52..e94f6a5 100644
--- a/bench/bench_rpc.c
+++ b/bench/bench_rpc.c
@@ -113,6 +113,7 @@ static void allocation_tracking_end(uint64_t *calls, uint64_t *bytes)

 struct sample {
 	uint64_t scheduled_ns, start_ns, submit_ns, end_ns;
+	uint64_t probe_lock_ns, probe_return_ns, probe_message_ns;
 	uint32_t bytes, method;
 	int submit_status, rpc_status, valid, scheduler_dropped;
 };
@@ -394,7 +395,7 @@ static const char *compression_name(uint32_t compression)
 	}
 }

-static enum tr_rpc_status echo_v2(struct tr_rpc_v2_call_id call,
+static enum tr_rpc_status echo_v2_impl(struct tr_rpc_v2_call_id call,
                                   const struct tr_rpc_v2_request *request,
                                   const struct tr_rpc_v2_cancel *cancel,
                                   struct tr_rpc_v2_reply *reply, void *arg)
@@ -423,6 +424,33 @@ static enum tr_rpc_status echo_v2(struct tr_rpc_v2_call_id call,
 	return TR_RPC_STATUS_OK;
 }

+struct tr_unary_probe_event {
+	uint64_t sequence, begin_ns, end_ns;
+	int status;
+};
+static struct tr_unary_probe_event tr_unary_probe_events[32768];
+static atomic_uint tr_unary_probe_count;
+static enum tr_rpc_status echo_v2(struct tr_rpc_v2_call_id call,
+                                  const struct tr_rpc_v2_request *request,
+                                  const struct tr_rpc_v2_cancel *cancel,
+                                  struct tr_rpc_v2_reply *reply, void *arg)
+{
+	if (request->kind != TR_RPC_V2_REQUEST_MESSAGE || request->body.len < 8U)
+		return echo_v2_impl(call, request, cancel, reply, arg);
+	unsigned index = atomic_fetch_add_explicit(&tr_unary_probe_count, 1U,
+	                                           memory_order_relaxed);
+	if (index >= 32768U)
+		abort();
+	struct tr_unary_probe_event *event = &tr_unary_probe_events[index];
+	for (unsigned i = 0U; i < 8U; ++i)
+		event->sequence |= (uint64_t)request->body.data[i] << (8U * i);
+	event->begin_ns = now_ns();
+	enum tr_rpc_status result = echo_v2_impl(call, request, cancel, reply, arg);
+	event->end_ns = now_ns();
+	event->status = result;
+	return result;
+}
+
 static int run_server(const struct options *o)
 {
 	struct tr_server_config config;
@@ -560,6 +588,14 @@ static int run_server(const struct options *o)
 		       stats.peers_ready_total, stats.peers_reaped_total);
 	}
 	destroy_server_retry(server);
+	fprintf(stderr, "{\"type\":\"unary_server_stage_probe\",\"events\":[");
+	for (unsigned i = 0U; i < atomic_load(&tr_unary_probe_count); ++i) {
+		struct tr_unary_probe_event *event = &tr_unary_probe_events[i];
+		fprintf(stderr, "%s[%" PRIu64 ",%" PRIu64 ",%" PRIu64 ",%d]",
+		        i ? "," : "", event->sequence, event->begin_ns,
+		        event->end_ns, event->status);
+	}
+	fprintf(stderr, "]}\n");
 	return status == TR_OK ? EXIT_SUCCESS : EXIT_FAILURE;
 }

@@ -574,6 +610,7 @@ static void result_message(struct tr_rpc_v2_call call,
 		run->bad_callback = 1;
 	} else {
 		slot->message_seen = 1;
+		slot->sample->probe_message_ns = now_ns();
 		slot->response_valid =
 		        response && response->len == slot->sample->bytes &&
 		        response->data &&
@@ -974,11 +1011,21 @@ static void report_open_phase(const struct sample *samples, uint32_t count,
 	free(ok_lat);
 }

+static uint64_t probe_thread_cpu_ns(void)
+{
+	struct timespec value;
+	check(clock_gettime(CLOCK_THREAD_CPUTIME_ID, &value), "probe thread CPU");
+	return (uint64_t)value.tv_sec * UINT64_C(1000000000) +
+	       (uint64_t)value.tv_nsec;
+}
+
 static int open_phase(struct client_run *run, const struct options *o)
 {
 	struct sample *samples = calloc(o->requests, sizeof(*samples));
 	struct rusage before, after;
 	uint64_t begin, horizon, guard, end;
+	uint64_t probe_cpu_begin = probe_thread_cpu_ns();
+	uint64_t probe_pid = (uint64_t)(uint32_t)getpid();
 	uint64_t allocation_calls = 0U, allocation_bytes = 0U;
 	uint32_t i;
 	int failed = 0;
@@ -1005,7 +1052,7 @@ static int open_phase(struct client_run *run, const struct options *o)
 		struct tr_rpc_v2_call call;
 		struct tr_rpc_v2_client_callbacks callbacks;
 		struct tr_rpc_bytes request;
-		uint64_t sequence = i;
+		uint64_t sequence = (probe_pid << 32U) | i;
 		uint32_t j;
 		int ret;

@@ -1017,6 +1064,7 @@ static int open_phase(struct client_run *run, const struct options *o)
 		s->start_ns = now_ns();

 		check(pthread_mutex_lock(&run->lock), "open lock");
+		s->probe_lock_ns = now_ns();
 		for (j = 0; j < run->window; ++j) {
 			if (run->slots[j].busy && run->slots[j].done)
 				run->slots[j].busy = 0;
@@ -1056,6 +1104,7 @@ static int open_phase(struct client_run *run, const struct options *o)
 		                           &request, &call_options, &callbacks,
 		                           &call);

+		s->probe_return_ns = now_ns();
 		check(pthread_mutex_lock(&run->lock), "open submit lock");
 		s->submit_status = ret;
 		if (ret != TR_OK) {
@@ -1107,6 +1156,22 @@ static int open_phase(struct client_run *run, const struct options *o)
 		return -1;
 	}

+	fprintf(stderr, "{\"type\":\"rpc_admission_probe\","
+	        "\"main_thread_cpu_ns\":%" PRIu64 ",\"begin_ns\":%" PRIu64
+	        ",\"end_ns\":%" PRIu64 ",\"columns\":[\"scheduled_ns\","
+	        "\"wake_ns\",\"lock_acquired_ns\",\"submit_ns\","
+	        "\"api_return_ns\",\"terminal_ns\",\"submit_status\","
+	        "\"scheduler_dropped\",\"message_callback_ns\"],\"samples\":[",
+	        probe_thread_cpu_ns() - probe_cpu_begin, begin, end);
+	for (uint32_t sample = 0U; sample < o->requests; ++sample) {
+		const struct sample *s = &samples[sample];
+		fprintf(stderr, "%s[%" PRIu64 ",%" PRIu64 ",%" PRIu64 ",%" PRIu64
+		        ",%" PRIu64 ",%" PRIu64 ",%d,%d,%" PRIu64 "]", sample ? "," : "",
+		        s->scheduled_ns, s->start_ns, s->probe_lock_ns,
+		        s->submit_ns, s->probe_return_ns, s->end_ns,
+		        s->submit_status, s->scheduler_dropped, s->probe_message_ns);
+	}
+	fprintf(stderr, "]}\n");
 	report_open_phase(samples, o->requests, o->rate_rps, begin, horizon,
 	                  end, cpu_seconds(&after) - cpu_seconds(&before),
 	                  after.ru_maxrss, run->window, allocation_calls,

