diff --git a/src/rpc/rpc_record_client.c b/src/rpc/rpc_record_client.c
index 0648247..8e3a4fb 100644
--- a/src/rpc/rpc_record_client.c
+++ b/src/rpc/rpc_record_client.c
@@ -9,13 +9,38 @@
 #include "tr/status.h"

 #include <stdbool.h>
+#include <stdio.h>
+#include <inttypes.h>
 #include <stddef.h>
 #include <stdatomic.h>
 #include <stdlib.h>
 #include <string.h>
 #include <time.h>

